BEGIN;
SELECT pg_advisory_xact_lock(hashtextextended('trait-approved-catalogue-20260928',0));
INSERT INTO app.businesses(slug,display_name) VALUES('trait-fish-meat-hub','TRAIT Fish & Meat Hub') ON CONFLICT(slug) DO NOTHING;
DO $import$
DECLARE business uuid; cat uuid; item jsonb; product uuid; created integer:=0;
BEGIN
 SELECT id INTO business FROM app.businesses WHERE slug='trait-fish-meat-hub' AND display_name='TRAIT Fish & Meat Hub' AND is_active AND deleted_at IS NULL FOR UPDATE;
 IF business IS NULL THEN RAISE EXCEPTION 'Business identity differs; review required'; END IF;
