}]},{"key":"red-snapper","category":"SEAFOOD","name":"Red Snapper","pricePaise":70000,"pricingBasis":"RAW_WEIGHT","priceUnit":"kg","unitGrams":1000,"unitsPerTray":null,"sizeNote":null,"image":null,"sort":6,"weights":[1000],"quantities":[],"preparations":[{"name":"Whole"},{"name":"Fillet"},{"name":"Boneless Steak/Cubes"},{"name":"Butterfly"},{"name":"Finger Cut"},{"name":"Full Fish Grill/Baking Cut"}]},{"key":"indian-salmon","category":"SEAFOOD","name":"Indian Salmon","pricePaise":120000,"pricingBasis":"RAW_WEIGHT","priceUnit":"kg","unitGrams":1000,"unitsPerTray":null,"sizeNote":null,"image":null,"sort":7,"weights":[1000],"quantities":[],"preparations":[{"name":"Whole"},{"name":"Fillet"},{"name":"Boneless Steak/Cubes"},{"name":"Butterfly"},{"name":"Finger Cut"},{"name":"Full Fish Grill/Baking Cut"}]},{"key":"seabass-pandugappa","category":"SEAFOOD","name":"Seabass / Pandugappa","pricePaise":80000,"pricingBasis":"RAW_WEIGHT","priceUnit":"kg","unitGrams":1000,"unitsPerTray":null,"sizeNote":null,"image":null,"sort":8,"weights":[1000],"quantities":[],"preparations":[{"name":"Whole"},{"name":"Fillet"},{"name":"Boneless Steak/Cubes"},{"name":"Butterfly"},{"name":"Finger Cut"},{"name":"Full Fish Grill/Baking Cut"}]},{"key":"anchovies-nettali","category":"SEAFOOD","name":"Anchovies / Nettali","pricePaise":38000,"pricingBasis":"RAW_WEIGHT","priceUnit":"kg","unitGrams":1000,"unitsPerTray":null,"sizeNote":null,"image":null,"sort":9,"weights":[1000],"quantities":[],"preparations":[{"name":"Whole"}]},{"key":"white-snapper","category":"SEAFOOD","name":"White Snapper","pricePaise":70000,"pricingBasis":"RAW_WEIGHT","priceUnit":"kg","unitGrams":1000,"unitsPerTray":null,"sizeNote":null,"image":null,"sort":10,"weights":[1000],"quantities":[],"preparations":[{"name":"Whole"},{"name":"Fillet"},{"name":"Boneless Steak/Cubes"},{"name":"Butterfly"},{"name":"Finger Cut"},{"name":"Full Fish Grill/Baking Cut"}]},{"key":"big-anchovies","category":"SEAFOOD","name":"Big Anchovies","pricePaise":46