 INSERT INTO app.categories(business_id,name,sort_order) VALUES(business,item->>'category',CASE item->>'category' WHEN 'EGGS' THEN 0 WHEN 'SEAFOOD' THEN 1 ELSE 2 END) ON CONFLICT(business_id,name) DO NOTHING;
 SELECT id INTO cat FROM app.categories WHERE business_id=business AND name=item->>'category';
 SELECT id INTO product FROM app.products WHERE business_id=business AND name=item->>'name';
 IF product IS NULL THEN
 INSERT INTO app.products(business_id,category_id,name,description,allowed_weights,preparations,pricing_basis,price_unit_grams,units_per_pack,sale_quantities,catalogue_price_paise,catalogue_published,sort_order)
 VALUES(business,cat,item->>'name',COALESCE(item->>'sizeNote',''),item->'weights',item->'preparations',item->>'pricingBasis',(item->>'unitGrams')::integer,(item->>'unitsPerTray')::integer,item->'quantities',(item->>'pricePaise')::bigint,true,(item->>'sort')::integer) RETURNING id INTO product;
 created:=created+1;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM app.products p WHERE p.id=product AND p.pricing_basis=item->>'pricingBasis' AND p.catalogue_price_paise=(item->>'pricePaise')::bigint AND p.price_unit_grams IS NOT DISTINCT FROM (item->>'unitGrams')::integer AND p.units_per_pack IS NOT DISTINCT FROM (item->>'unitsPerTray')::integer) THEN RAISE EXCEPTION 'Existing product differs; no overwrite'; END IF;
 END IF;
 END LOOP;
 IF created>0 THEN PERFORM app.core_audit(business,NULL,NULL,'SYSTEM','APPROVED_CATALOGUE_IMPORTED',business,jsonb_build_object('productsCreated',created,'source','Approved catalogue 2026-09-28')); END IF;
END; $import$;
COMMIT;
SELECT json_build_object('businessId',b.id,'products',(SELECT json_agg(json_build_object('id',p.id,'name',p.name)) FROM app.products p WHERE p.business_id=b.id)) AS imported FROM app.businesses b WHERE b.slug='trait-fish-meat-hub';
